from pathlib import Path
import pandas as pd, numpy as np, json, csv, hashlib
ROOT=Path(__file__).resolve().parents[3]; OUT=ROOT/'audit/loop5_8'; SRC=ROOT/'audit/loop5_7/recomputed_cell_results.csv'
df=pd.read_csv(SRC); df['gap']=df.mean_stability-df.mean_external_ari; df['eligible']=df.degenerate_repeats_5pct<=3
nd=df[df.eligible]; cohorts=['colon','srbct','cns','leukemia','prostate','ovarian']; by=nd.groupby('dataset').gap.agg(['mean','count']).reindex(cohorts)
means=by['mean'].to_numpy(); counts=by['count'].to_numpy(); cell=float(nd.gap.mean()); equal=float(means.mean())
def gen(seed,B=10000):
 idx=np.random.default_rng(seed).integers(0,6,size=(B,6)); e2=means[idx].mean(1); e1=(means[idx]*counts[idx]).sum(1)/counts[idx].sum(1)
 return {'seed':seed,'B':B,'cell_weighted_ci':[float(x) for x in np.quantile(e1,[.025,.975])],'equal_cohort_ci':[float(x) for x in np.quantile(e2,[.025,.975])],'cell_weighted_bootstrap_mean':float(e1.mean()),'equal_cohort_bootstrap_mean':float(e2.mean())}
seeds=[0,1,7,42,123,2025,99173]; reps=[gen(s) for s in seeds]
# Reproduce the code path in audit_degeneracy.py: rng.choice strings, two function calls, sequential same RNG.
rng=np.random.default_rng(42); cs=np.array(cohorts); seq=[]; first=[]
for ix in range(10000): first.append(float(means[0]) if False else 0)
# vector draws per iteration preserve method's RNG consumption precisely
allmeans=df.groupby('dataset').gap.mean().reindex(cohorts).to_numpy(); seq_all=[]; seq_nd=[]
for _ in range(10000):
 ix=np.array([cohorts.index(c) for c in rng.choice(cs,size=6,replace=True)]);seq_all.append(float(allmeans[ix].mean()))
for _ in range(10000):
 ix=np.array([cohorts.index(c) for c in rng.choice(cs,size=6,replace=True)]);seq_nd.append(float(means[ix].mean()))
hist_ci=[float(x) for x in np.quantile(seq_nd,[.025,.975])]
# Historical make_stability_outputs.py uses shared integer bootstrap indices for both populations.
rng2=np.random.default_rng(42);bootidx=rng2.integers(0,6,size=(10000,6)); make_ci=[float(x) for x in np.quantile(means[bootidx].mean(1),[.025,.975])]
with open(OUT/'bootstrap_seed_sensitivity.csv','w',newline='',encoding='utf-8') as f:
 fields=['seed','B','cell_weighted_ci_lower','cell_weighted_ci_upper','equal_cohort_ci_lower','equal_cohort_ci_upper','cell_weighted_bootstrap_mean','equal_cohort_bootstrap_mean','seed_role']
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for r in reps:w.writerow({'seed':r['seed'],'B':r['B'],'cell_weighted_ci_lower':r['cell_weighted_ci'][0],'cell_weighted_ci_upper':r['cell_weighted_ci'][1],'equal_cohort_ci_lower':r['equal_cohort_ci'][0],'equal_cohort_ci_upper':r['equal_cohort_ci'][1],'cell_weighted_bootstrap_mean':r['cell_weighted_bootstrap_mean'],'equal_cohort_bootstrap_mean':r['equal_cohort_bootstrap_mean'],'seed_role':'fresh seeded cluster bootstrap'})
 for label,ci in [('audit_degeneracy.py exact sequential rng.choice',hist_ci),('make_stability_outputs.py shared rng.integers',make_ci)]: w.writerow({'seed':42,'B':10000,'equal_cohort_ci_lower':ci[0],'equal_cohort_ci_upper':ci[1],'seed_role':label})
# comparison includes estimand3 cluster bootstrap as procedure for each point statistic
rows=[]
def add(name,point,ci,weighting,interpret): rows.append({'estimand_or_procedure':name,'point_estimate':point,'ci_lower':ci[0],'ci_upper':ci[1],'weighting':weighting,'interpretation':interpret})
seed42=next(r for r in reps if r['seed']==42)
add('E1: cell-weighted eligible-cell mean; cluster bootstrap CI',cell,seed42['cell_weighted_ci'],'60 eligible cohort-method cells equal weight at point estimate; bootstrap cohort copies weighted by observed eligible-cell count','Point and interval target cell-weighted mean; assumes cohorts are exchangeable/sample from target cohort population; exploratory only (6 clusters).')
add('E2: equal-cohort mean; cluster bootstrap CI',equal,seed42['equal_cohort_ci'],'Each cohort mean equal weight at point and bootstrap','Targets average cohort in this six-cohort frame; population inference still assumes cohort exchangeability.')
add('E3: historical sequential-RNG cohort-cluster procedure',equal,hist_ci,'Equal-cohort point; resample six cohorts and preserve eligible method cells; historical audit_degeneracy RNG call sequence','Same target as E2; RNG consumption changes the interval but not the estimand.')
add('Historical manuscript combination',cell,make_ci,'Cell-weighted point 0.485376; manuscript CI produced by equal-cohort resampling','Mismatched point and interval estimand; remove from primary manuscript.')
with open(OUT/'bootstrap_estimand_comparison.csv','w',newline='',encoding='utf-8') as f:
 w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows(rows)
result={'source':str(SRC.relative_to(ROOT)),'source_sha256':hashlib.sha256(SRC.read_bytes()).hexdigest(),'source_type':'reconstructed 72 cell aggregates; raw repeat values not resampled','eligibility':'degenerate_repeats_5pct <= 3 of 30; all six cohorts included','cohort_order':cohorts,'eligible_cell_count':int(len(nd)),'eligible_cells_per_cohort':{c:int(by.loc[c,'count']) for c in cohorts},'cohort_mean_gap':{c:float(by.loc[c,'mean']) for c in cohorts},'estimand1_cell_weighted_point':cell,'estimand2_equal_cohort_point':equal,'seed42_cluster_bootstrap':seed42,'historical_audit_degeneracy_sequential_ci':hist_ci,'historical_make_stability_outputs_ci':make_ci,'historical_manuscript_ci_rounds_to':[round(make_ci[0],3),round(make_ci[1],3)],'number_of_bootstrap_replicates':10000,'bootstrap_unit':'cohort; 6 clusters; all eligible method cells retained within sampled cohort','recommended_primary_reporting':'Describe cohort-specific values and cell-weighted descriptive mean; remove inferential interval from primary manuscript. Any cohort bootstrap is exploratory pending a defensible cohort sampling frame.','limitations':['Only six nonrandomly selected biomedical cohorts; exchangeability unsupported.','Method cells within each cohort are not independent cohorts.','The 435 pairwise ARIs entering each stability estimate are dependent and are not bootstrap units here.','Bootstrap uses aggregate cell metrics, not repeat-level uncertainty.','Historical bootstrap code paths differ and RNG consumption is order-sensitive.']}
(OUT/'bootstrap_recalculation.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8')
text='''# Bootstrap estimand audit\n\n## Evidence inspected\n\nThe exact current repository has no `paper/manuscript/main.tex`; the file referenced in prior loops is unavailable in this checkout. The reviewed archived manuscript is `paper/archive/main_dami_revision_historical.tex` (historical manuscript, not authenticated as the target final). Its abstract and contribution claim report a cell-weighted nondegenerate gap of 0.485376 with cohort-bootstrap 95% CI [0.379, 0.662]. Historical code inspected: `D:/Final Year Project/scripts/audit_degeneracy.py` and `scripts/make_stability_outputs.py`; aggregate inputs used: `audit/loop5_7/recomputed_cell_results.csv` (60 eligible cells derived from recovered partitions). No model reruns were done.\n\nThe nondegenerate population is Rule (i′): a method-cohort cell is retained when its smallest cluster is at least 5% of the sampled partition in at least 27 of 30 repeats (`degenerate_repeats_5pct <= 3`). It contains 60 cells: CNS 8, Colon 11, Leukemia 11, Ovarian 11, Prostate 9, SRBCT 10. The gap is `mean_stability - mean_external_ARI`, with each component first computed as the cell's mean over its saved pairwise (435) and repeat (30) values.\n\n## Estimands and results\n\nEstimand 1 weights every eligible cohort-method cell equally: the descriptive point estimate is **0.485376**. For a cluster bootstrap that targets this cell-weighted estimand, each draw samples six cohort labels and pools all selected cohort copies' cells before averaging. With seed 42 and 10,000 resamples, its percentile interval is **[0.377121, 0.644985]**. This gives greater weight to cohorts contributing more eligible methods.\n\nEstimand 2 computes the mean of each cohort's eligible-method mean, then weights the six cohorts equally: **0.499925**. Its seed-42, 10,000-resample cohort-cluster percentile interval is **[0.378581, 0.661716]**. This targets the mean of the represented cohort means, but a broader cohort-population interpretation requires a defensible sampling frame/exchangeability assumption that is not established. The historical sequential-RNG path gives **[0.381104, 0.653002]** for this same equal-cohort estimand.\n\nEstimand 3 is the cohort-cluster resampling procedure, not a third target quantity: use the cell-weighted ratio statistic for E1 or the mean of cohort means for E2, keeping each sampled cohort's complete eligible-method structure. Results for E1, E2 and the historical RNG variant are shown separately in the CSV. This avoids treating methods or the 435 dependent pairwise comparisons as independent units. Six clusters make percentile intervals coarse and model-dependent. Neither provides confirmatory population-level inference.\n\n## Historical code mismatch\n\n`make_stability_outputs.py` uses one seed-42 array of integer cohort resamples for both all-cell and nondegenerate intervals. Its nondegenerate interval reproduces the archived manuscript rounding [0.379, 0.662], but the bootstrap statistic is equal-cohort average while the printed point estimate is an equal-cell mean (0.485376). `audit_degeneracy.py` separately uses a single RNG across two sequential `rng.choice` loops; its equal-cohort interval is [0.381104, 0.653002] and depends on this call order. The two implementations therefore do not define a stable published CI workflow. Loop 5.7's sequential-RNG reconstruction and the manuscript output should not be conflated; this audit exposes source-level implementation variants.\n\n## Recommendation\n\n**Remove the inferential interval from the primary manuscript.** Report the six cohort-specific descriptive results and, if desired, the 0.485376 equal-cell summary labelled as descriptive over the 60 eligible cells. State explicitly that the six cohorts are not a random sample of biomedical cohorts. If an interval is retained in supplementary exploratory material, name the estimand, give the exact resampling statistic/seed/code, and call it a cohort-clustered sensitivity interval rather than confirmatory evidence. Do not infer zero predictive utility from correlation tests, or treat a positive interval as universal generalization.\n\n## Limitations\n\nThe calculations bootstrap reconstructed cell aggregates; they do not propagate uncertainty from repeated partitions, nor model the dependence among the 435 pairwise ARIs. The saved partitions support reconstructing each cell's descriptive metrics, but only six datasets are available. The currently reviewed manuscript source is an archive copy, so these corrections must be reconciled against the true intended manuscript before editing.\n'''
(OUT/'bootstrap_estimand_audit.md').write_text(text,encoding='utf-8')
print('wrote bootstrap deliverables',len(rows),len(reps),'seed rows')
